using Health_Care_System.BLL.Interfaces; using Health_Care_System.BLL.Models; using Health_Care_System.Entities;
namespace Health_Care_System.BLL.Services;
public sealed class AppointmentService:IAppointmentService { private readonly IUnitOfWork _uow; public AppointmentService(IUnitOfWork uow)=>_uow=uow; public async Task<Result<PaginatedList<Appointment>>> GetAllAsync(string? searchValue,int pageIndex,int pageSize){var data=await _uow.Appointments.GetAllAsync();if(!string.IsNullOrWhiteSpace(searchValue))data=data.Where(x=>x.Doctor.Name.Contains(searchValue,StringComparison.OrdinalIgnoreCase)||x.Patient.Name.Contains(searchValue,StringComparison.OrdinalIgnoreCase));return Result<PaginatedList<Appointment>>.Success(PaginatedList<Appointment>.Create(data,pageIndex,pageSize));} public async Task<Result<Appointment>> GetByIdAsync(int patientId,int doctorId){var item=await _uow.Appointments.GetAsync(patientId,doctorId);return item is null?Result<Appointment>.Failure("Appointment not found."):Result<Appointment>.Success(item);} public async Task<Result<Appointment>> CreateAsync(Appointment entity){await _uow.Appointments.CreateAsync(entity);await _uow.SaveChangesAsync();return Result<Appointment>.Success(entity);} public async Task<Result<Appointment>> UpdateAsync(Appointment entity){var item=await _uow.Appointments.GetAsync(entity.PatientId,entity.DoctorId);if(item is null)return Result<Appointment>.Failure("Appointment not found.");item.AppointmentDate=entity.AppointmentDate;_uow.Appointments.Update(item);await _uow.SaveChangesAsync();return Result<Appointment>.Success(item);} public async Task<Result<Appointment>> DeleteAsync(int patientId,int doctorId){var item=await _uow.Appointments.GetAsync(patientId,doctorId);if(item is null)return Result<Appointment>.Failure("Appointment not found.");_uow.Appointments.Delete(item);await _uow.SaveChangesAsync();return Result<Appointment>.Success(item);} }
